/**
 * Scratch page for T8 — every level, actually playable, with the ball's state on screen.
 * Not part of the game; served at /ball.html.
 *
 * This is what PLAN.md §T8's acceptance check is done on: spawn in level 001's pocket and
 * drive the ball through the hoops. It runs the real `Playfield` at the original's 25 Hz,
 * so what is on screen is the shipped simulation and not a preview approximation — the
 * only things it adds are the level switcher, the state readout and three debug toggles.
 *
 * T10 replaces it with a `PlayState` that has the real HUD, menus and level flow. Until
 * then this is also the fastest way to answer "does that feel right?".
 *
 * T9 added the sound. `Playfield`'s `onSound` is handed straight to `AudioPlayer`, so the
 * three OTT tones fire on exactly the events `e`'s switch assigns them to — `pickup` on a
 * crystal, a crystal ball, any of the three boosts and the open door, `up` on a hoop, and
 * `pop` on a death. WebAudio stays locked until the first gesture, so the first keypress
 * is silent by design.
 */
import { Application, Container, Graphics, Sprite, Text, type Spritesheet } from 'pixi.js';

import { hdEnabled, loadSheet, sheetLabel } from './sheet.ts';

import { AudioPlayer } from '../core/Audio.ts';

import { DYING } from '../game/Ball.ts';
import { VIEW_HEIGHT, VIEW_WIDTH } from '../game/Camera.ts';
import { Level, TILE_SIZE, type LevelJson } from '../game/Level.ts';
import { KEY_LEFT, KEY_RIGHT, KEY_UP } from '../game/Physics.ts';
import { Playfield } from '../game/Playfield.ts';
import { TileMap } from '../game/TileMap.ts';
import { HUD_COLOUR } from '../game/Tiles.ts';

const LEVEL_COUNT = 11;
const TICK_MS = 40;
const ZOOM = 4;
/** Where the text under the 128x128 screen starts, in canvas pixels. */
const TEXT_TOP = 16 + 128 * ZOOM + 8;

type Scene = {
  field: Playfield;
  map: TileMap;
  ball: Sprite;
  root: Container;
};

const held = new Set<string>();
let scene: Scene | null = null;
let invincible = false;
let paused = false;
/** Advance exactly one tick while paused, for reading a collision frame by frame. */
let stepOnce = false;

async function loadLevel(id: number): Promise<LevelJson> {
  const name = String(id).padStart(3, '0');
  const response = await fetch(`levels/${name}.json`);
  if (!response.ok) throw new Error(`levels/${name}.json: ${response.status}`);
  return (await response.json()) as LevelJson;
}

function status(): string {
  if (!scene) return '';
  const { field } = scene;
  const { ball } = field;
  const boosts = [
    ball.speedTicks > 0 ? `speed ${ball.speedTicks}` : '',
    ball.gravityTicks > 0 ? `inverted ${ball.gravityTicks}` : '',
    ball.jumpTicks > 0 ? `jump ${ball.jumpTicks}` : '',
  ].filter(Boolean);

  return [
    `level ${String(field.level.id).padStart(2, '0')}`,
    `ball ${ball.x},${ball.y} (${ball.size}px)`,
    `v ${ball.vx},${ball.vy}`,
    `hoops ${field.hoopsTaken}/${field.level.hoopCount}`,
    `score ${field.score}`,
    `lives ${field.lives}`,
    `door ${field.door.offset}/24${field.door.open ? ' open' : ''}`,
    boosts.length > 0 ? boosts.join(' ') : '',
    field.gameOver ? 'GAME OVER' : field.levelComplete ? 'COMPLETE' : '',
    invincible ? 'invincible' : '',
    paused ? 'paused' : '',
  ]
    .filter(Boolean)
    .join('   ');
}

async function main(): Promise<void> {
  const canvas = document.getElementById('ball-canvas') as HTMLCanvasElement;
  const app = new Application();
  await app.init({ canvas, background: 0x14141a, resizeTo: window, antialias: false });

  // H3: the HD sheet by default, `?hd=0` for the pre-HD look.
  const hd = hdEnabled();
  const sheet: Spritesheet = await loadSheet(hd);

  // Loading the tones can fail on a cold cache or a browser with no WebAudio; a silent
  // preview is better than one that will not start.
  const audio = new AudioPlayer();
  await audio.load().catch((error: unknown) => console.error(error));
  audio.installUnlockListeners();

  const stage = new Container();
  stage.scale.set(ZOOM);
  stage.position.set(16, 16);
  app.stage.addChild(stage);

  const info = new Text({
    text: '',
    resolution: 2,
    style: { fill: 0xd0d0d8, fontFamily: 'monospace', fontSize: 12 },
  });
  info.position.set(16, TEXT_TOP);
  app.stage.addChild(info);

  const help = new Text({
    text: [
      'arrows / WASD move     space / up bounces     [ ] previous / next level     R restart',
      'I invincibility     P pause     . single tick while paused',
      `atlas: ${sheetLabel(hd)}`,
    ].join('\n'),
    resolution: 2,
    style: { fill: 0x8a8a96, fontFamily: 'monospace', fontSize: 12 },
  });
  help.position.set(16, TEXT_TOP + 24);
  app.stage.addChild(help);

  // Level JSON is fetched, so two quick presses would race each other's teardown; builds
  // are queued and `wanted` — not the live scene, which lags — is what the keys step.
  let loading: Promise<void> = Promise.resolve();
  let wanted = 1;
  const show = (id: number): Promise<void> => {
    wanted = id;
    loading = loading.then(() => build(id)).catch((error: unknown) => console.error(error));
    return loading;
  };

  async function build(id: number): Promise<void> {
    scene?.map.destroy();
    scene?.root.destroy({ children: true });
    stage.removeChildren();

    const level = new Level(await loadLevel(id));
    const field = new Playfield(level, {
      invincible,
      onSound: (effect) => audio.play(effect),
    });
    const map = new TileMap(level, sheet, { door: field.door });

    const root = new Container();
    const ball = new Sprite();
    // `e.a(Graphics)` draws the ball between the two tile layers: the back half of a hoop
    // is painted before it and the front half after, which is how the ball appears to
    // pass through the ring.
    root.addChild(map.view, ball, map.front);

    const hud = new Graphics()
      .rect(0, VIEW_HEIGHT + 1, VIEW_WIDTH, 128 - VIEW_HEIGHT - 1)
      .fill(HUD_COLOUR);
    root.addChild(hud);

    // A mask belongs to one target, so each clipped layer gets its own.
    for (const layer of [map.view, ball, map.front]) {
      const mask = new Graphics().rect(0, 0, VIEW_WIDTH, VIEW_HEIGHT).fill(0xffffff);
      root.addChild(mask);
      layer.mask = mask;
    }

    stage.addChild(root);
    scene = { field, map, ball, root };
  }

  await show(1);

  window.addEventListener('keydown', (event) => {
    const key = event.key.toLowerCase();
    held.add(key);
    if ([' ', 'arrowup', 'arrowdown', 'arrowleft', 'arrowright'].includes(key)) {
      event.preventDefault();
    }
    const current = wanted;
    if (event.key === '[') void show(((current + LEVEL_COUNT - 2) % LEVEL_COUNT) + 1);
    if (event.key === ']') void show((current % LEVEL_COUNT) + 1);
    if (key === 'r') void show(current);
    if (key === 'p') paused = !paused;
    if (key === '.') stepOnce = true;
    if (key === 'i') {
      invincible = !invincible;
      void show(current);
    }
  });
  window.addEventListener('keyup', (event) => held.delete(event.key.toLowerCase()));
  // A dropped focus mid-jump would otherwise leave a direction held down forever.
  window.addEventListener('blur', () => held.clear());

  /** The three gameplay keys, mapped the way `src/core/Input.ts` binds them. */
  function pushKeys(field: Playfield): void {
    const bits: [number, boolean][] = [
      [KEY_LEFT, held.has('arrowleft') || held.has('a')],
      [KEY_RIGHT, held.has('arrowright') || held.has('d')],
      [KEY_UP, held.has('arrowup') || held.has('w') || held.has(' ')],
    ];
    for (const [bit, down] of bits) {
      if (down) field.ball.pressKey(bit);
      else field.ball.releaseKey(bit);
    }
  }

  let accumulator = 0;
  app.ticker.add((ticker) => {
    accumulator += ticker.deltaMS;
    // Five ticks of catch-up, like `src/core/Loop.ts`; a tab switch should not fast-forward.
    accumulator = Math.min(accumulator, TICK_MS * 5);

    while (accumulator >= TICK_MS) {
      accumulator -= TICK_MS;
      if (!scene) continue;
      if (paused && !stepOnce) continue;
      stepOnce = false;
      pushKeys(scene.field);
      scene.field.tick();
    }
    if (paused && stepOnce && scene) {
      // Held time may not have covered a whole tick; a single press still steps one.
      stepOnce = false;
      pushKeys(scene.field);
      scene.field.tick();
    }

    if (!scene) return;
    const { field, map, ball } = scene;
    map.update(field.camera.x, field.camera.y);

    // `e.a(Graphics)` draws the burst sprite from a fixed 6px offset while dying, and the
    // ball from its own radius otherwise.
    const dying = field.ball.state === DYING;
    ball.texture =
      sheet.textures[dying ? 'ball_burst' : field.ball.size === 16 ? 'ball_large' : 'ball_small']!;
    const offset = dying ? TILE_SIZE / 2 : field.ball.radius;
    ball.position.set(
      field.ball.x - offset - field.camera.x,
      field.ball.y - offset - field.camera.y,
    );

    info.text = status();
  });
}

void main();
